// Vistas documentales del resultado: no ejecutan el solver ni simulan resultados.
function planTabs(view) {
  return `<div class="tabs" role="group" aria-label="Área de estrategia">${[['summary','Carrera'],['advanced','Datos'],['plan','Plan'],['revisions','Revisiones']].map(([id,label]) => `<button data-view="${id}" aria-pressed="${id === view || (id === 'plan' && ['stint','pit','calculation'].includes(view))}">${label}</button>`).join('')}</div>`;
}
function previewButton(label, view, selected = false) {
  return `<button class="orbit-btn orbit-btn--ghost ${selected ? 'selected-segment' : ''}" data-view="${view}">${label}</button>`;
}
function previewTimeline(view) {
  return panel('Desarrollo de la carrera', `<p class="muted">Esquema de navegación · sin resultado calculado</p><div class="plan-timeline"><span>Salida</span>${previewButton('Stint', 'stint', view === 'stint')}<span class="connector"></span>${previewButton('Parada', 'pit', view === 'pit')}<span class="connector"></span><span>Llegada</span></div>`);
}
function previewTable(headings, rows) {
  return `<div class="table-scroll"><table><thead><tr>${headings.map(h => `<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(cells => `<tr>${cells.map(c => `<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
}
function planPreview(source, view) {
  const title = {plan:'Tu plan de carrera',stint:'Detalle del stint',pit:'Detalle de la parada',calculation:'Proceso de cálculo',revisions:'Revisiones del plan'}[view];
  let body = '';
  if (view === 'plan') body = `<div class="plan-metrics">${['Tiempo previsto','Paradas','Fuel inicial','Energía virtual','Margen de llegada'].map(label=>`<div class="panel"><span>${label}</span><strong>—</strong></div>`).join('')}</div>${previewTimeline(view)}<div class="detail-grid">${panel('Detalle del plan', '<p class="muted">Selecciona Stint o Parada para recorrer el diseño del detalle. El motor todavía no está conectado.</p>')}${panel('Por qué este plan', row('Objetivo','Tras calcular')+row('Restricciones','Tras calcular')+row('Supuestos y límites','Tras calcular'))}</div>`;
  if (view === 'stint') body = `${previewTimeline(view)}<div class="detail-grid"><div class="stack">${panel('Piloto y ritmo', row('Piloto',esc(state.driver || 'Por confirmar'))+row('Ritmo previsto','— s/vuelta')+row('Vueltas / duración','—'))}${panel('Recursos del stint',previewTable(['Recurso','Inicio','Final','Reserva'],[['Combustible','— L','— L','— L'],['Energía virtual','— %','— %','— %'],['Neumáticos','—','—','—']]))}${panel('Evolución prevista','<div class="plot-empty">Fuel · Energía virtual · Desgaste<br>Curvas disponibles tras calcular</div>')}</div>${panel('Qué condiciona este stint',row('Límite de combustible','Por determinar')+row('Límite de energía virtual','Por determinar')+row('Neumáticos y piloto','Por determinar')+row('Datos de origen','Por determinar')+`<div class="source-actions">${previewButton('Ver parada siguiente','pit')}</div>`)}</div>`;
  if (view === 'pit') body = `${previewTimeline(view)}<div class="detail-grid"><div class="stack">${panel('Operaciones previstas',previewTable(['Servicio','Acción','Duración','Origen'],[['Combustible','Según cálculo','— s','Datos y reglas'],['Energía virtual','Según reglamento','—','Datos y reglas'],['Neumáticos','Según cálculo','— s','Datos y reglas'],['Cambio de piloto','Según cálculo','— s','Reglas']]))}${panel('Secuencia del servicio','<div class="service-flow"><span>Tránsito de entrada</span><span>Servicios<br><small>Simultaneidad según reglamento</small></span><span>Tránsito de salida</span></div><p class="form-note">Esquema: los servicios simultáneos no se suman como si fueran consecutivos.</p>')}</div><div class="stack">${panel('Por qué parar aquí',row('Recurso limitante','Tras calcular')+row('Ventana reglamentaria','Tras calcular')+row('Relevo y margen al entrar','Tras calcular'))}${panel('Tiempo y coste',row('Tiempo detenido','— s')+row('Tiempo total en boxes','— s')+row('Pérdida frente a seguir en pista','— s')+`<div class="source-actions">${previewButton('Ver stint','stint')}</div>`)}</div></div>`;
  if (view === 'calculation') body = `<div class="detail-grid">${panel('Etapas previstas', '<ol class="calculation-stages"><li>Comprobar datos y reglas</li><li>Evaluar planes factibles</li><li>Seleccionar el mejor plan</li><li>Verificar la carrera completa</li></ol><p class="muted">Vista del proceso previsto. No hay un cálculo ejecutándose, porcentajes ni resultados simulados.</p>')}${panel('Entradas y supuestos',row('Evento y reglas','Revisión elegida')+row('Sesiones y correcciones','Revisión elegida')+row('Incidentes imprevistos','Fuera del cálculo inicial')+row('Fuel / energía virtual','Comprobaciones separadas'))}</div>`;
  if (view === 'revisions') body = panel('Todavía no hay revisiones guardadas','<p class="muted">El guardado no está conectado. Cada revisión conservará las reglas, fuentes, correcciones y resultado utilizados. La recarga descarta este borrador demostrativo.</p>');
  return `<div class="page plan-page"><div class="page-head"><div><div class="breadcrumb">${source.track} / Esquema visual</div><h2 tabindex="-1">${title}</h2><p>LMU · ${source.category} · Valores pendientes del motor</p></div></div>${planTabs(view)}${body}<footer class="wizard-footer"><span class="muted">Originales intactos</span><div class="source-actions">${previewButton('Volver al borrador','summary')}${previewButton('Ver proceso de cálculo','calculation')}${button('Calcular estrategia','',true,true)}</div></footer></div>`;
}
